    bentarrow/.style={->, bend right=90}]
    \tikzstyle{split}=[rectangle split,rectangle split parts=2,draw,text centered]
    \tikzstyle{every node}=[font=\footnotesize]


    \node[split] (A) {Diffusion Approximation \nodepart{second} $\wass(\dtlaw,\ctlaw) \leq \dots$};

    \coordinate (BelowA) at ($(A.south)+ (0,-0.7cm)$);
    \node[split, left=0.7cm of BelowA] (B) {Lemma~\ref{lem:MSEbd} \nodepart{second} $\wass(\dtlaw,\ytlaw) \leq \dots$};

    \draw[bentarrow] (B.north) |- (A.west);




    \node[split,right=0.8cm of B] (C44) {Corollary~\ref{cor:Villani} \cite{bolley2005weighted} \nodepart{second} $\wass(\ytlaw,\ctlaw) \leq C \,f(\KL(\ytlaw\|\ctlaw))$};
    \coordinate (BelowC44) at ($(C44.south)+ (0,-0.7cm)$);
    \draw[bentarrow] (C44.north) |- (A.east);

    \node[split, below=0.2cm of C44] (L75) {Lemma~\ref{lem:exp_int} \nodepart{second} $C \leq \dots$};

    \node[split, left=1.3cm of BelowC44] (L52) {Lemma~\ref{lem:KL_bd} \nodepart{second} $\KL(\ytlaw\|\ctlaw) \leq \dots$};

    \draw[bentarrow] (L52.north) |- (C44.west);

    \draw[->] (L75.north) -- (C44.south);











    \node[split, right=5cm of A] (D) {Diffusion Convergence  \nodepart{second} $\wass(\ctlaw,\gibbs) \leq \dots$};
    \node[split, below=0.15cm of D] (E) {Lemma~\ref{lem:OVthm} \cite{bakry2014analysis} \nodepart{second} $\wass(\ctlaw,\gibbs) \leq \sqrt{2\LSconst\KL(\ctlaw\|\gibbs)}$};

    \node[split, below=0.2cm of E] (F) {Lemma~\ref{lem:expdecay} \cite{bakry2014analysis} \nodepart{second} $\KL (\ctlaw|| \gibbs) \leq \KL(\idistrw || \gibbs)e^{-2k\step/\beta \LSconst}$};

    \coordinate (BelowF) at ($(F.south)+ (0,-0.6cm)$);
    \node[split, left=1cm of BelowF] (G) {Proposition~\ref{prop:logsob} \nodepart{second} $\gibbs$ satisfies log-Sobolev inequality, with $\LSconst \leq \dots$};

    \draw[bentarrow] (G.east) -| (F.south);




    \node[split, above=0.25cm of $(A.north)!0.5!(D.north)$] (Process) {Main result (Theorem~\ref{thm:main1}) \nodepart{second} $\wass(\dtlaw,\gibbs) \leq \dots$};




    \draw[bentarrow] (A.north) |- (Process.west);
    \draw[bentarrow] (D.north) |- (Process.east);




    \draw[->] (F.north) -- (E.south);
    \draw[->] (E.north) -- (D.south);

\end{tikzpicture}}
\caption{\small Theorem~\ref{thm:main1} proof structure. First the 2-Wasserstein distance between discrete-time algorithm \eqref{eq:dt_sgld} (with measure $\dtlaw$) and continuous-time diffusion \eqref{eq:ct_diff} (with measure $\ctlaw$) is bounded. We must introduce an intermediate process (with law $\ytlaw$). Lemma~\ref{lem:MSEbd} bounds the Wasserstein distance between $\dtlaw$ and $\ytlaw$. Lemma~\ref{lem:KL_bd} bounds the KL-divergence between $\dtlaw$ and $\ytlaw$. Corollary~\ref{cor:Villani} is then used, along with Lemma~\ref{lem:exp_int} to relate this KL bound to a 2-Wasserstein bound. Proposition~\ref{prop:logsob} is the key tool in bounding $\wass(\ctlaw,\gibbs)$, establishing that $\gibbs$ satisfies a log-Sobolev inequality. We then employ exponential decay of entropy (Lemma~\ref{lem:expdecay}) and the Otto-Villani Theorem (Lemma~\ref{lem:OVthm}) to obtain exponential decay of $\wass(\ctlaw,\gibbs)$.}
\label{fig:blockdiag}
\end{figure}

